import { describe, it, expect, vi, beforeEach } from 'vitest'
import UserDashboard from './UserDashboard'

describe('UserDashboard', () => {
  beforeEach(() => {
    vi.restoreAllMocks()
  })

  it('fetches user preferences with cache: no-store', async () => {
    const mockPreferences = { theme: 'dark' }
    global.fetch = vi.fn().mockResolvedValue({
      json: () => Promise.resolve(mockPreferences),
    })

    const jsx = await UserDashboard()
    expect(global.fetch).toHaveBeenCalledWith('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    expect(jsx).toBeDefined()
  })

  it('handles fetch failure and returns fallback mock data', async () => {
    global.fetch = vi.fn().mockRejectedValue(new Error('Network error'))

    const jsx = await UserDashboard()
    expect(jsx).toBeDefined()
  })
})

